// ❌ Thảm họa useState + useEffect thủ công:
// Khủng hoảng loading, error, race condition, 0 cache, 0 dedup!
function UserProfile({ userId }) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let isMounted = true;
    fetchUser(userId).then(res => {
      if (isMounted) { setData(res); setLoading(false); }
    });
    return () => { isMounted = false; }; // Phải tự ngắt race condition!
  }, [userId]);

  if (loading) return <Spinner />;
  return <div>{data.name}</div>;
}

